import heapq

def prev(l,d,k,c,t):
  if l+d*(k-1)+c<=t: a=l+d*(k-1)
  elif t<l+c: a=-1
  else: a=l+d*((t-l)//d)
  return a

def dijkstra(P,T,v,s):
  H,T[v]=[],s
  heapq.heappush(H,(-s,v))

  while H:
    t,v=heapq.heappop(H)
    if T[v]>-t: continue
    for l,d,k,c,a in P[v]:
      s=prev(l,d,k,c,-t)
      if T[a]<s:
        T[a]=s
        heapq.heappush(H,(-s,a))

